                remove_gain = before_i - after_i
                for j in range(rcount):
                    if i == j:
                        continue
                    rj = routes[j]
                    if route_load(rj) + dc > cap:
                        continue
                    for ins in range(len(rj) + 1):
                        new_rj = rj[:ins] + [c] + rj[ins:]
                        add_gain = route_cost(rj) - route_cost(new_rj)
                        gain = remove_gain + add_gain
                        if gain > best_gain + 1e-12 or (gain == best_gain and best_move is not None and (i, j, pos, ins, c) < best_move):
                            best_gain = gain
                            best_move = (i, j, pos, ins, c)
        if best_move is None:
            return False
        i, j, pos, ins, c = best_move
        ri = routes[i]
        rj = routes[j]
        ri2 = ri[:pos] + ri[pos + 1:]
        rj2 = rj[:ins] + [c] + rj[ins:]
        if ri2:
            routes[i] = ri2
        else:
            routes.pop(i)
            if i < j:
                j -= 1
        routes[j] = rj2
        return True

    # Apply a few improvement rounds
    for _ in range(3):
        changed = True
        while changed:
            changed = try_relocate(routes)

        # Two-route swap / 2-opt style exchange (lightweight)
        improved = False
        for i in range(len(routes)):
            for j in range(i + 1, len(routes)):
                ri = routes[i]
                rj = routes[j]
                li = route_load(ri)
                lj = route_load(rj)
                for a in range(len(ri)):
                    for b in range(len(rj)):
                        ca = ri[a]
                        cb = rj[b]
                        nai = li - demands[ca] + demands[cb]
                        naj = lj - demands[cb] + demands[ca]
                        if nai > cap or naj > cap:
                            continue
                        old = route_cost(ri) + route_cost(rj)
                        nri = ri[:a] + [cb] + ri[a + 1:]
                        nrj = rj[:b] + [ca] + rj[b + 1:]
                        new = route_cost(nri) + route_cost(nrj)
                        if new + 1e-12 < old or (new == old and (ca, cb) < (cb, ca)):
                            routes[i] = nri
                            routes[j] = nrj
                            improved = True
                            break
                    if improved:
                        break
                if improved:
                    break
            if improved:
                break
        if not improved:
            break

    # Final normalization: ensure all customers exactly once
    seen = set()
    final_routes = []
    for route in routes:
        nr = []
        load = 0
        for c in route:
            if c in seen:
                continue
            if load + demands[c] <= cap:
                nr.append(c)
                seen.add(c)
                load += demands[c]
        if nr:
            final_routes.append(nr)

    missing = [c for c in customers if c not in seen]
    for c in missing:
        placed = False
        for r in final_routes:
            if route_load(r) + demands[c] <= cap:
                r.append(c)
                placed = True
                break
        if not placed:
            final_routes.append([c])

    return final_routes
